CREATE VIEW public.v_servicing_stage_cards AS SELECT NULL::text AS card_id, NULL::text AS hotel_id, NULL::text AS hotel_name, NULL::text AS service_line, NULL::text AS service_variant, NULL::boolean AS orm_lite, NULL::text AS current_stage, NULL::timestamptz AS stage_entered_at, NULL::timestamptz AS created_at, NULL::timestamptz AS go_live_at, NULL::integer AS progress_done, NULL::integer AS progress_total, NULL::timestamptz AS last_updated, NULL::text AS ae_owner_id, NULL::text AS specialist_id, NULL::text AS orm_team, NULL::text AS marcom_owner_id, NULL::text AS hotel_status, NULL::boolean AS assignment_complete, true AS pending_sync FROM public.crm_documents WHERE false;
CREATE VIEW public.v_servicing_stat AS SELECT NULL::integer AS cards_total, NULL::integer AS hotels, NULL::integer AS go_live, NULL::integer AS in_progress, NULL::integer AS awaiting_caretaker, true AS pending_sync WHERE false;
CREATE VIEW public.v_servicing_pipeline AS SELECT current_stage AS stage, service_line, NULL::integer AS card_count, pending_sync FROM public.v_servicing_stage_cards WHERE false;
CREATE VIEW public.v_servicing_golive_days AS SELECT card_id, hotel_id, hotel_name, service_line, created_at, go_live_at, NULL::integer AS overall_days, NULL::text AS cohort_month, pending_sync FROM public.v_servicing_stage_cards WHERE false;
CREATE VIEW public.v_servicing_assignment_gaps AS SELECT card_id, hotel_id, hotel_name, service_line, current_stage, NULL::text[] AS missing_roles, pending_sync FROM public.v_servicing_stage_cards WHERE false;
GRANT SELECT ON public.v_servicing_stage_cards, public.v_servicing_stat, public.v_servicing_pipeline, public.v_servicing_golive_days, public.v_servicing_assignment_gaps TO anon, authenticated, service_role;
COMMENT ON VIEW public.v_servicing_stage_cards IS 'Pending Cloud mirror: Servicing cards/stage events/checklists and the assignment master are browser-local. Empty until seed+C5; never inferred.';
COMMENT ON VIEW public.v_servicing_stat IS 'Pending Servicing mirror. Five stat numbers are derived client-side from v_servicing_stage_cards rows.';
COMMENT ON VIEW public.v_servicing_pipeline IS 'Pending Servicing mirror. Count per (stage x service_line); First Sync counts MT only.';
COMMENT ON VIEW public.v_servicing_golive_days IS 'Pending Servicing mirror. Old KPI #4 per-card create->go-live days; median+IQR only.';
COMMENT ON VIEW public.v_servicing_assignment_gaps IS 'Pending Servicing mirror. ORM needs AE+Specialist+ORM team; Marcom needs AE+Specialist+Marcom person.';